// The shape of everything the build reads out of the repository.
//
// The JSON beside this file is generated by `web/scripts/*.mjs` and is git-ignored. This file is
// source, and it is the compile-time half of a deliberate pair of guards:
//
//   * a generator that stops emitting a key is a **TypeScript error at the call site** that reads
//     it — which is where somebody can see what the missing value was for;
//   * a generator that emits a key nothing reads is caught by review, and a generator that emits a
//     *wrong* value is caught by the suites in `web/tests`.
//
// The pair matters because the failure being guarded against is Mihon's, and it is silent: an `<a>`
// whose `href` came back `undefined` renders as a button that looks right and does nothing. There
// are twelve release assets on `/download`, so there are twelve chances to ship it.

/** One published file in a GitHub release. */
export interface ReleaseAsset {
  name: string;
  url: string;
  size: number;
  /** From `SHA256SUMS`. `null` when the release has no checksum file — never a fabricated digest. */
  sha256: string | null;
}

export interface ReleaseData {
  tag: string;
  version: string;
  publishedAt: string;
  htmlUrl: string;
  /** The first section of the release body, as sanitised HTML. */
  whatChanged: string;
  /**
   * Keyed by the name `scripts/lib/release.sh`'s `release_manifest` prints — exactly twelve keys.
   *
   * A bijection, checked at generation time in both directions: a manifest line with no asset is a
   * platform that silently failed to build, and an asset with no manifest line is a name nothing in
   * this repository knows how to compose. Either exits 1 naming the file.
   */
  assets: Record<string, ReleaseAsset>;
  /**
   * Whether `SHA256SUMS.sig` is published beside the checksums.
   *
   * `/download`'s signing section renders only when this is true. It is false today and the page
   * must say what tracker L-81 says in its own words: the lane verifies integrity, not provenance,
   * because no signing key exists yet. A download page claiming signature verification against that
   * register would be the exact failure the honesty rule exists to prevent.
   */
  hasSignature: boolean;
}

export interface ServiceEntry {
  name: string;
  kind: "tracker" | "rendezvous";
  endpoints: string[];
  operator: string | null;
  /**
   * The published index this service was read from, as an ABSOLUTE URL, exactly as its publisher
   * spells it. It is data, not a link: `storeOfferHref` turns it into one, once, at the render site.
   *
   * It was called `storeUrl` and held a finished `/add-store?url=…` href, while the service table
   * composed that href a second time — so every "Add to NoderaMC" button shipped double-encoded and
   * the deep-link page refused it as malformed. The name now says which of the two things it is, and
   * `storeOfferHref` throws when handed its own output, so the pair cannot be confused again quietly.
   */
  storeIndexUrl: string;
}

export interface ServicesData {
  /** Which of `services.py`'s five resolution steps answered, in its own words. */
  source: string;
  fetchedAt: string;
  services: ServiceEntry[];
}

export interface RoadmapCategory {
  category: string;
  tasks: number;
  done: number;
  inProgress: number;
  blocked: number;
}

export interface LimitationRow {
  id: string;
  /** The category directory the register was found in — from the glob, never a hand-kept list. */
  register: string;
  gap: string;
  whyNotPermanent: string;
  eliminationPath: string;
  owner: string;
  /** The §B "Owner" cell is a `[n](Task.n.md)` link; this is where it points, when it points. */
  ownerUrl: string | null;
  exitTest: string;
  /** The raw Status cell. It can run to four hundred words, and that is the point of it. */
  status: string;
  /**
   * The first word of `status`, uppercased — or `ENVELOPE` for a §A row.
   *
   * A §A envelope constraint has no status column, because it does not burn down: that is what §A
   * means. Giving those rows a fourth value rather than defaulting them to `OPEN` is the difference
   * between saying "this is a different kind of row" and claiming the register recorded something it
   * did not.
   */
  state: "OPEN" | "RETIRING" | "RETIRED" | "ENVELOPE";
}

export interface StatusData {
  /** ROADMAP's own "Snapshot: YYYY-MM-DD". */
  snapshot: string;
  categories: RoadmapCategory[];
  /**
   * Summed from `categories`. Published; the overall percentage is not.
   *
   * `docs/ROADMAP.md` says in its own words that the weighting behind its completion figure is not
   * derivable from its tables, and that inventing one would be worse than a stale figure that says
   * so. This site does not invent one either: it shows what is derivable and quotes the sentence.
   */
  done: number;
  total: number;
  /** ROADMAP's sentence about why the percentage is not recomputed, verbatim. */
  notRecomputed: string;
  /** From the `badges` orphan branch. `null` when it has never been fetched — never zero. */
  tests: { passed: number; failed: number } | null;
  /**
   * How many `docs/*\/LIMITATIONS.md` registers were read.
   *
   * A GLOB count, never a literal. Two earlier plans wrote "nine" from memory; it was eleven, and it
   * is ten since the app and mobile categories merged into `frontend`. A number typed into a page is
   * a number that is wrong on the day the tree changes and right in every review until then.
   */
  registerCount: number;
  /** Every §B row of every register. */
  limitations: LimitationRow[];
  /** Every §A row — envelope constraints, rendered as a separate and shorter table. */
  envelope: LimitationRow[];
}

/** The two `:root[data-theme]` blocks of the launcher's stylesheet, as flat maps. */
export interface ThemeTokens {
  dark: Record<string, string>;
  light: Record<string, string>;
}

export interface MirrorEntry {
  /** Repository-relative source path, or `<ref>:<path>` for a file on another branch. */
  source: string;
  route: string;
  title: string;
  description: string;
  /** The rendered document. */
  html: string;
  /** `git log -1 --format=%cI` for the source. `null` in a shallow clone that cannot know. */
  updatedAt: string | null;
  /** Where the source is edited on GitHub. */
  editUrl: string;
  toc: { depth: 2 | 3; id: string; text: string }[];
}

export interface MirrorData {
  entries: MirrorEntry[];
}
